INSERT INTO `author_requests` VALUES (1,'Eiichiro Oda','Male','ru-- chitamahale180904@gmail.com','scrypt:32768:8:1$XxGu0KSjtQAj8DcX$c96e0d6dd6e631fb03a2c3c8ed973a8f3b221ed243437ca29b652d851a5ab228ee40f957b4760f0e5034cc47c23453f48202f66658f438138ed43ad423399a3d','Eiichiro Oda is a Japanese manga artist best known as the creator of One Piece, one of the most successful manga series of all time. Born in Kumamoto, Japan, he showed an early interest in drawing and storytelling and began his professional career in his late teens. Oda gained major recognition after One Piece debuted in 1997. He is praised for his imaginative world-building, memorable characters, and emotional storytelling. The series has broken multiple records, cementing Oda’s influence in modern manga culture.','1975-01-01','approved','2025-12-29 11:21:09','2025-12-29 11:24:40'),(2,'Eiichiro Oda','Male','ruchitamahale180904@gmail.com','scrypt:32768:8:1$XxGu0KSjtQAj8DcX$c96e0d6dd6e631fb03a2c3c8ed973a8f3b221ed243437ca29b652d851a5ab228ee40f957b4760f0e5034cc47c23453f48202f66658f438138ed43ad423399a3d','Eiichiro Oda is a Japanese manga artist best known as the creator of One Piece, one of the most successful manga series of all time. Born in Kumamoto, Japan, he showed an early interest in drawing and storytelling and began his professional career in his late teens. Oda gained major recognition after One Piece debuted in 1997. He is praised for his imaginative world-building, memorable characters, and emotional storytelling. The series has broken multiple records, cementing Oda’s influence in modern manga culture.','1975-01-01','approved','2025-12-29 11:21:09','2025-12-29 11:24:40'),(3,'lowen','Female','lowen@gmail.com','scrypt:32768:8:1$LObgEVGmCrDEoZ6f$2946633dcd52adadf3dbd6a5c23002f90a7d070492a6dede86c64c2a867fffed8084d5991bbba0a28f647c518c80286af86681f065b68fb44da8f99848b58f67','hii its good to meet you fdjfkdjfkldsjfkldsfjkdsfjkdlfjdsklfjsdklfjsdkkkkkkkkkkkkkkkkkkkkkkkkkkkkkdfsdnkldsnfnvfvnmcxvnsfjoh fghsjlhsd fhsdjfhsdjfhsjfdshjlhjjhhdfjf hj fhadjfhsdj  dfhjdsfhjasdfh  dfjsdjfsdjfhdsjfh d dfadsfsdf','2002-02-20','approved','2026-03-18 06:18:11','2026-03-18 06:18:59'),(4,'Liz Tomforde','Female','liz@gmail.com','scrypt:32768:8:1$fuGw8E7bm29ZxmE0$9576cddb720de01837418e6828739f9b0389e7c41a1988d7818ae05df6e629097ced467e8854ad714e08276fb2158cccbc43d08c2c6116e2ff6d74a44b667912','Liz Tomforde is a New York Times bestselling author of sports romance novels that depict realistic and healthy relationships. Her books offer a mix of witty banter, undeniable chemistry, a healthy dash of spice, and swoon-worthy men who look good in a uniform.\r\n\r\nBorn and raised in Northern California, Liz is the youngest of five children. She loves all things romance, traveling, dogs, and hockey. When she\'s not traveling or writing, Liz can be found relaxing at home or listening to a good audiobook while on a walk with her Golden Retriever, Luke.\r\n\r\nFor more information, please visit Liz’s website and subscribe to her newsletter at liztomforde.com. You can connect also with Liz on Instagram @liztomforde.author.','2026-04-01','approved','2026-04-03 10:18:27','2026-04-03 10:19:23'),(5,'Lowen Ashleigh','Female','Lowen123@gmail.com','scrypt:32768:8:1$LrlJVMi0V37f5etF$50618068ec94993d6c6d3004d62ee0a5a72501a9e8c146d6ec6c9a5bdf25c7ca015a5e18af4bed97282f01ad67e2607980225c4ec985abc5842a7ec0af94582d','Lowen Ashleigh is a contemporary American author known for her emotionally intense and deeply introspective fiction. Her work often explores themes of grief, isolation, resilience, and the darker corners of the human psyche. Writing with raw honesty, Lowen has built a reputation for creating characters that feel painfully real and stories that linger long after the final page.\r\n\r\nBefore gaining wider recognition, Lowen spent years navigating financial hardship and personal loss, experiences that heavily influence her writing voice. Her prose is intimate and unfiltered, often blurring the line between vulnerability and unease.\r\n\r\nThough initially under the radar, her work began reaching a broader audience after a pivotal opportunity connected her to the literary world in unexpected ways. Despite her rising recognition, Lowen remains a private individual, preferring solitude and focusing on her craft over public attention.\r\n\r\nWhen she’s not writing, she is known to live quietly, drawing inspiration from everyday moments and the complexities of human behavior.',NULL,'approved','2026-04-03 11:58:42','2026-04-10 15:20:54'),(6,'Liz Tomforde','Female','liza@gmail.com','scrypt:32768:8:1$kRKodlI7U35ZwBO2$f2b13d300ebb5be8de23f152c28baa0ea41ff846564bbde8e137d7673a791ddc6173cad77b138bd5bd04837e0dbf80d1bd9714cd1d2496e9d2adf6458b6166a8','Liz Tomforde is a New York Times bestselling author of sports romance novels that depict realistic and healthy relationships. Her books offer a mix of witty banter, undeniable chemistry, a healthy dash of spice, and swoon-worthy men who look good in a uniform.\r\n\r\nBorn and raised in Northern California, Liz is the youngest of five children. She loves all things romance, traveling, dogs, and hockey. When she\'s not traveling or writing, Liz can be found relaxing at home or listening to a good audiobook while on a walk with her Golden Retriever, Luke.',NULL,'pending','2026-04-10 15:24:08',NULL);
