--
-- Table structure for table `reviews`
--

DROP TABLE IF EXISTS `reviews`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `reviews` (
  `review_id` int NOT NULL AUTO_INCREMENT,
  `user_id` int DEFAULT NULL,
  `book_id` int DEFAULT NULL,
  `ratings` int NOT NULL,
  `review_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `review_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`review_id`),
  UNIQUE KEY `unique_user_book` (`user_id`,`book_id`),
  KEY `user_id` (`user_id`),
  KEY `book_id` (`book_id`),
  CONSTRAINT `fk_reviews_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `reviews_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`),
  CONSTRAINT `reviews_ibfk_2` FOREIGN KEY (`book_id`) REFERENCES `books` (`book_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1400 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `reviews`
--

LOCK TABLES `reviews` WRITE;
/*!40000 ALTER TABLE `reviews` DISABLE KEYS */;
INSERT INTO `reviews` VALUES (1,3,53,5,'nice','2025-11-24 08:42:52'),(2,4,53,3,'It was a nice book but not my type','2025-11-24 08:53:03'),(4,5,53,4,NULL,'2025-11-24 08:53:50'),(5,2,53,5,'it was nice book','2025-11-24 08:56:59'),(6,2,7,4,'One of the amazing books I have read','2025-11-24 09:03:52'),(7,6,53,4,NULL,'2025-11-24 10:19:52'),(8,6,58,3,'too much of fantasy...far from reality','2025-11-24 10:22:08'),(9,3,10,5,'OMG!!! It\'s one of the best horror books i have \"ever\" read....I suggest everyone to try this one if you loovvveeeeee horror','2025-11-24 17:57:01'),(10,2,5,4,NULL,'2025-11-25 06:53:01'),(11,2,26,5,'Felt Goosebumps!!!','2025-11-25 06:53:50'),(12,2,4,4,'Currently reading Sapiens by Yuval Noah Harari, and wow, it’s already blowing my mind.\r\nHarari’s way of explaining human evolution, belief systems, and how societies formed is so clear and fascinating.\r\nWill update once I finish!','2025-11-25 06:55:52'),(13,7,56,3,'A poignant story set during Partition, but the emotional connection felt a bit limited for me.\r\nKhushwant Singh captures the chaos and brutality of the time very realistically, and the setting is incredibly vivid.\r\nHowever, I couldn’t fully connect with the characters, and some parts felt slow.\r\nA good, important read — just not a personal favourite.','2025-11-25 07:11:08'),(16,9,82,5,NULL,'2025-11-25 07:17:00'),(17,10,90,5,'oo god!!! the chase.....','2025-11-25 07:25:21'),(18,10,91,5,'I need my Christian Harper so badddd.......','2025-11-25 07:26:46'),(19,11,18,2,'Finished Steve Jobs.\r\nWell-researched but too long and too dry for me.\r\nI struggled to stay engaged, and the narration felt repetitive at times.\r\nA 2-star read.','2025-11-25 07:30:41'),(20,17,24,5,'I watched this disaster unfold in real time. Way too much angst, zero communication, and an unhealthy amount of emotional damage. Alex is terrifyingly devoted, Ava is too forgiving, and somehow it still works. Would I recommend this love story? maybe. Did I survive it? Barely.','2026-03-29 08:46:13'),(21,17,91,4,'“I knew Christian was dangerous, but watching him fall in love was… unsettling. He loves quietly, obsessively, and with terrifying patience. Stella deserved better communication, but somehow she chose him anyway. Do I trust him? No. Would I stand between them? Also no. I value my life.','2025-12-25 16:37:25'),(22,18,88,5,'love this book.........','2026-01-09 17:25:52'),(23,21,101,5,'loved it......','2026-02-28 15:25:39'),(25,18,91,5,'“It’s… actually a really interesting story. Stella meets this man, Christian, and he’s very calm, very put-together—the kind of person who always seems in control. And he really cares about her… in a very intense way.\r\n\r\nI think Stella feels safe with him, and that matters a lot. Even if… sometimes the way he loves is a little overwhelming.\r\n\r\nIt’s not a perfect kind of love, but it’s real in its own way. And if Stella is happy, then I think that’s what counts most.”','2026-03-29 08:53:26'),(26,18,89,5,'Ugh, Bridget’s life is literally insane ? Like imagine being a whole princess and falling for your bodyguard?? And not just any bodyguard—that man. The tension?? I was living for it.\r\n\r\nFrom my POV, her story is way more intense than mine. It’s all stolen moments, “we shouldn’t do this,” and him being all cold but secretly obsessed with her. And Bridget?? She really had to grow up fast and carry a whole country on her back while dealing with feelings like that. I was stressed for her.','2026-03-29 09:03:43'),(27,17,89,5,'Ugh, Bridget’s life is literally insane ? Like imagine being a whole princess and falling for your bodyguard?? And not just any bodyguard—that man. The tension?? I was living for it.\r\n\r\nFrom my POV, her story is way more intense than mine. It’s all stolen moments, “we shouldn’t do this,” and him being all cold but secretly obsessed with her. And Bridget?? She really had to grow up fast and carry a whole country on her back while dealing with feelings like that. I was stressed for her.','2026-03-29 09:09:01'),(28,23,81,5,'Well, when I finished reading this book, I was confused if I finished the book or book finished me. \r\nThat said, it’s definitely not an easy read. Some parts are disturbing, even disturbing enough to make you pause. The relationships are messy and toxic, and none of the characters feel completely trustworthy or even likable.\r\n\r\noverall Verity is one of those books that you don’t exactly “enjoy” in a traditional sense, but you can’t ignore either. It’s intense, unsettling, and unforgettable—definitely not for everyone, but if you like dark, twisty stories that mess with your head, it’s worth the read.','2026-04-01 16:46:27'),(29,24,2,5,'I loves jk rowling\'s harry potter\'s series and I fell in love with reading with this book for me its 10 on 10 book loved it so much..','2026-04-02 04:15:24'),(30,25,24,3,'Just finished reading this book. it good for one time go but to be honest it did fasinate me a lot.','2026-04-02 04:21:48'),(31,26,96,4,'loved it','2026-04-02 04:24:52'),(32,27,24,4,'Dude this book was just wow...\r\nI love how Ana describe each characters. story line is fine not top rated but fine , so I belive one can enjoy this book.','2026-04-02 04:28:12'),(33,28,16,5,'i just love this book. well who doesn\'t love a classic spider-man.','2026-04-02 04:32:04'),(35,29,101,4,'Many people will find it boring because it doesnt contain any twist and turns. But I love it','2026-04-02 04:35:57'),(37,20,24,5,'Loved the chemistry between Alex and Ava. The story had a perfect mix of romance and emotional depth. Couldn\'t stop reading!','2026-04-15 02:00:39'),(38,20,89,5,'The royal romance trope was done so well! Rhys and Bridget’s story was intense and addictive.','2026-04-15 02:01:30'),(39,20,90,5,'Enemies-to-lovers done right! The banter between Josh and Jules was top-tier.','2026-04-15 02:01:59'),(40,19,24,4,'Really engaging storyline with strong characters. Some parts felt a bit predictable, but overall a great read.','2026-04-15 02:03:41'),(41,19,89,4,'Loved the slow-burn relationship. The political elements added a nice twist, though pacing was slightly slow in the middle.','2026-04-15 02:03:59'),(42,19,90,4,'Fun and spicy read. Some emotional moments felt rushed, but the chemistry carried the story.','2026-04-15 02:04:17'),(43,19,91,4,'Loved the tension and mystery. Stella’s character development was great, though ending felt slightly stretched.','2026-04-15 02:04:35'),(44,18,90,5,'The banter between male and female protagonists was just on another level!!!','2026-04-15 02:23:42'),(45,24,131,5,'I love this teenage romance. wesly made me feel butterflies, and love the wat les doesn\'t change herself for anyone.\r\n\r\nOver all it was so much fun for me to read it.','2026-05-07 08:44:53'),(46,24,90,5,'loveed it soo damn much.....','2026-08-17 10:09:36'),(47,25,66,5,'Dune completely earned the hype. The world-building around Arrakis and the politics of House Atreides is on another level.','2026-09-01 12:30:00'),(48,25,43,5,'1984 is unsettling in exactly the way it should be. Orwell\'s vision of surveillance feels more relevant every year.','2026-09-02 12:30:00'),(49,25,100,4,'Atomic Habits gave me a genuinely useful framework, though some of the stories felt repeated for emphasis.','2026-09-03 12:30:00'),(50,25,124,5,'Clean Code changed how I write functions and name variables. Some of the examples feel dated but the principles hold up.','2026-09-04 12:30:00'),(51,25,149,4,'Cracking the Coding Interview is exactly what it promises -- dense, practical, and worth the grind before interviews.','2026-09-05 12:30:00'),(52,25,152,4,'Operating System Concepts is thorough to the point of being a bit dry, but the process scheduling chapters were genuinely clarifying.','2026-09-06 12:30:00'),(53,4,76,4,'Solid, dependable read. Angels & Demons delivered on what it promised.','2025-11-24 06:17:01'),(54,31,26,4,'Really enjoyed A Court of Thorns and Roses, though the middle dragged a little for me.','2025-11-27 17:19:34'),(55,5,64,5,'A Clash of Kings lived up to the hype and then some.','2025-12-03 17:31:32'),(56,5,41,3,'It\'s okay. Murder on the Orient Express didn\'t blow me away but I don\'t regret reading it.','2025-12-08 23:04:58'),(57,26,150,5,NULL,'2025-12-09 03:26:22'),(58,21,81,4,'Solid, dependable read. Verity delivered on what it promised.','2025-12-09 14:20:49'),(59,13,21,4,'Really enjoyed Indian Economy under Early British Rule 1757–1857, though the middle dragged a little for me.','2025-12-13 13:51:37'),(60,13,25,4,'Liked It Ends with Us a lot, just wish the ending had a bit more punch.','2025-12-16 21:01:17'),(61,9,2,2,'Struggled to stay engaged with Harry Potter and the Philosopher\'s Stone, kept putting it down.','2025-12-17 15:27:03'),(62,13,72,4,'Really enjoyed Crown of Midnight, though the middle dragged a little for me.','2025-12-22 13:20:21'),(63,11,72,4,'Crown of Midnight was a solid read overall, a few predictable beats but still worth it.','2025-12-23 09:08:17'),(64,25,18,4,NULL,'2025-12-25 22:38:26'),(65,27,87,2,'Struggled to stay engaged with Homo Deus, kept putting it down.','2025-12-30 07:46:19'),(66,19,46,2,'Expected more from The Great Gatsby given the reviews. Left a bit disappointed.','2025-12-30 08:55:54'),(67,5,56,4,'Train to Pakistan was well written, not perfect but definitely worth the time.','2026-01-01 03:04:31'),(68,27,41,4,'Solid, dependable read. Murder on the Orient Express delivered on what it promised.','2026-01-05 12:57:40'),(69,22,44,2,'Expected more from Animal Farm given the reviews. Left a bit disappointed.','2026-01-07 22:22:23'),(70,23,29,5,'Finished The Fault in Our Stars in two sittings. The pacing was perfect.','2026-01-12 23:11:42'),(71,25,109,3,'A Feast for Crows had potential but felt a bit uneven by the end.','2026-01-17 13:05:37'),(72,5,96,5,'Everything about A Shot At History: My Obsessive Journey to Olympic Gold worked for me -- the characters, the ending, all of it.','2026